        bare: { kid: 'Einer blanken Silberplatte ist das Licht egal. Sie braucht zuerst das Iod.', sci: 'Poliertes Silber ist nicht lichtempfindlich: Es muss zuerst ioduriert werden.' },
        shoot: { kid: 'Klick! Der Deckel ist ab, und der kleine Bär muss stillsitzen. Je länger die Belichtung, desto mehr zappelt er!', sci: 'Deckel ab: Das Objektiv ist {t} lang offen. Auf der Platte ist noch nichts zu sehen; das Bild ist latent.' },
        early: { kid: 'Die Platte hat die Kamera noch nicht gesehen. Nimm zuerst das Bild auf!', sci: 'Die Platte wurde nie belichtet: Quecksilber würde sie nur verschleiern.' },
