        faint: { kid: 'Kaum etwas! Die Belichtung war zu kurz. Schieb sie länger und versuche es mit einer neuen Platte.', sci: 'Unterbelichtet: {t} war für eine Platte von 1839 zu wenig, das Bild ist schwach.' },
        good: { kid: 'Ein schönes Bild! Man sieht den kleinen Bären und die Statue, ganz scharf.', sci: 'Gute Belichtung ({t}): Der Bär ist dort leicht unscharf, wo er sich bewegt hat, die Statue ist scharf.' },
        blurry: { kid: 'Das Bild ist hell, aber der Bär ist ein Fleck: So lange konnte er nicht stillhalten. Die Statue, die stillsteht, ist scharf.', sci: 'Hell, aber {t} ist lang: Der bewegte Bär ist verwischt, die ruhende Statue bleibt scharf.' },
        burnt: { kid: 'Viel zu lang: Das Bild ist ausgewaschen, und der Bär ist ein Geist.', sci: 'Überbelichtet ({t}): Die Lichter sind flach und ausgewaschen, und der Bär hat sich so bewegt, dass er ein Geist ist.' },
